queries.expr:
(
  (
    max by (cluster, region) (
      tuist_kura_capacity_admission_headroom_gibibytes{cluster="tuist-production"}
    )
    or
    (
      floor(0.85 * max by (cluster, region) (tuist_kura_capacity_allocatable_gibibytes{cluster="tuist-production"}))
      - max by (cluster, region) (tuist_kura_capacity_reserved_gibibytes{cluster="tuist-production"})
    )
  )
  - (
    predict_linear(
      max by (cluster, region) (tuist_kura_capacity_reserved_gibibytes{cluster="tuist-production"})[3d:30m],
      3 * 86400
    )
    - max by (cluster, region) (tuist_kura_capacity_reserved_gibibytes{cluster="tuist-production"})
  )
)
or
predict_linear(
  max by (cluster, region) (
    tuist_kura_capacity_admission_headroom_gibibytes{cluster="tuist-production"}
  )[3d:30m],
  3 * 86400
)

absent_over_time(
  tuist_oban_queue_oldest_available_age_seconds{
    cluster="tuist-production", queue="process_xcresult"
  }[10m]
)
or
absent_over_time(
  tuist_oban_queue_oldest_available_age_seconds{
    cluster="tuist-production", queue="process_build"
  }[10m]
)

count by (cluster, env, queue, node) (
  (
    (
      time() - max by (cluster, env, queue, node) (
        tuist_oban_node_last_attempt_timestamp_seconds{cluster="tuist-production", queue=~"process_xcresult|process_build"}
      ) < 900
    )
    unless
    (
      time() - max by (cluster, env, queue, node) (
        tuist_oban_node_last_completion_timestamp_seconds{cluster="tuist-production", queue=~"process_xcresult|process_build"}
      ) < 900
    )
  )
  or
  (
    max by (cluster, env, queue, node) (
      tuist_oban_node_queue_limit{cluster="tuist-production", queue=~"process_xcresult|process_build"}
    )
    unless on (cluster, env, queue, node)
    (
      time() - max by (cluster, env, queue, node) (
        tuist_oban_node_last_attempt_timestamp_seconds{cluster="tuist-production", queue=~"process_xcresult|process_build"}
      ) < 900
    )
    and on (cluster, env, queue)
    (
      min_over_time(
        max by (cluster, env, queue) (
          tuist_oban_queue_length_count{cluster="tuist-production", queue=~"process_xcresult|process_build", state="available"}
        )[15m:1m]
      ) > 0
    )
  )
)

count by (cluster, env, queue, node) (
  (
    max by (cluster, env, queue, node) (
      tuist_oban_node_executing_jobs_count{cluster="tuist-production", queue="process_xcresult"}
    )
    < on (cluster, env, queue, node)
    max by (cluster, env, queue, node) (
      tuist_oban_node_queue_limit{cluster="tuist-production", queue="process_xcresult"}
    )
  )
  and on (cluster, env, queue)
  (
    max by (cluster, env, queue) (
      tuist_oban_queue_length_count{cluster="tuist-production", queue="process_xcresult", state="available"}
    ) > 100
  )
)

histogram_quantile(0.5,
  sum by (cluster, region, tenant_id, pod, le) (
    increase(kura_segment_shed_age_seconds_bucket{cluster="tuist-production"}[1d])
    * on (cluster, pod) group_left(region, tenant_id)
      max by (cluster, pod, region, tenant_id) (kura_node_geo_info{cluster="tuist-production"})
  )
)
and on (cluster, pod) (
  min by (cluster, pod) (
    min_over_time(kura_backfill_ring_fullness_percent{cluster="tuist-production"}[1d])
  ) >= 100
)

histogram_quantile(0.5,
  sum by (cluster, region, tenant_id, pod, le) (
    increase(kura_segment_shed_age_seconds_bucket{cluster="tuist-production"}[3d])
    * on (cluster, pod) group_left(region, tenant_id)
      max by (cluster, pod, region, tenant_id) (kura_node_geo_info{cluster="tuist-production"})
  )
)
and on (cluster, pod) (
  min by (cluster, pod) (
    min_over_time(kura_backfill_ring_fullness_percent{cluster="tuist-production"}[3d])
  ) >= 100
)

histogram_quantile(0.90,
  sum by (le, path) (
    rate(tuist_prom_ex_phoenix_http_request_duration_milliseconds_bucket{
      path=~"/api/projects/:account_handle/:project_handle/(bundles|tests|runs)"
    }[5m])
  )
  or
  sum by (le, path) (
    rate(tuist_prom_ex_phoenix_http_request_duration_milliseconds_bucket{
      path=~"/api/projects/:account_handle/:project_handle/xcode/builds"
    }[5m])
  )
  or
  sum by (le, path) (
    rate(tuist_prom_ex_phoenix_http_request_duration_milliseconds_bucket{
      path=~"/:account_handle/:project_handle/previews/:id/app.ipa"
    }[5m])
  )
) > 30000

histogram_quantile(0.90,  
  sum by (le, path) (  
    rate(tuist_prom_ex_phoenix_http_request_duration_milliseconds_bucket{  
      path=~"/:account_handle/:project_handle.*|/api/projects/:account_handle/:project_handle.*",  
      path!~"/api/projects/:account_handle/:project_handle/(builds|tests|runs|bundles)",  
      path!~"/api/projects/:account_handle/:project_handle/xcode/builds",  
      path!~"/:account_handle/:project_handle/previews/:id/app.ipa"  
    }[5m])  
  )  
) > 2000  
and  
sum by (path) (  
  rate(tuist_prom_ex_phoenix_http_request_duration_milliseconds_count{  
    path=~"/:account_handle/:project_handle.*|/api/projects/:account_handle/:project_handle.*",  
    path!~"/api/projects/:account_handle/:project_handle/(builds|tests|runs|bundles)",  
    path!~"/api/projects/:account_handle/:project_handle/xcode/builds",  
    path!~"/:account_handle/:project_handle/previews/:id/app.ipa"  
  }[5m])  
) > 0.05

label_replace(
  sum by (cluster, region, reason) (
    increase(tuist_kura_lifecycle_provision_refused_count{cluster="tuist-production"}[30m])
  ),
  "operation", "provision", "", ""
)
or
label_replace(
  sum by (cluster, region, reason) (
    increase(tuist_kura_lifecycle_claim_apply_refused_count{cluster="tuist-production"}[30m])
  ),
  "operation", "claim_growth", "", ""
)

max by (cluster, env, namespace, deployment) (
  kube_deployment_spec_replicas{
    namespace=~"tuist|tuist-staging|tuist-canary",
    deployment="tuist-tuist-xcresult-processor"
  }
)
-
max by (cluster, env, namespace, deployment) (
  kube_deployment_status_replicas_available{
    namespace=~"tuist|tuist-staging|tuist-canary",
    deployment="tuist-tuist-xcresult-processor"
  }
)
> 0

max by (cluster, env, namespace, deployment) (
  kube_deployment_status_condition{
    namespace=~"tuist|tuist-staging|tuist-canary",
    deployment="tuist-tuist-xcresult-processor",
    condition="Progressing",
    reason="ProgressDeadlineExceeded",
    status="false"
  }
) > 0

max by (cluster, namespace, statefulset, region) (
  label_replace(
    max_over_time(kura_region_sync_lag_seconds{cluster="tuist-production"}[5m]),
    "statefulset", "$1", "pod", "(.+)-[0-9]+"
  )
)

max by (cluster, node, region) (
  kura:node_pool * on (cluster, pool) group_left(region) sgn(topk by (cluster, pool) (1, timestamp(kura:pool_region)))
)

max by (cluster, region) (
  tuist_kura_capacity_admission_headroom_gibibytes{cluster="tuist-production"}
)
or
(
  floor(0.85 * max by (cluster, region) (tuist_kura_capacity_allocatable_gibibytes{cluster="tuist-production"}))
  - max by (cluster, region) (tuist_kura_capacity_reserved_gibibytes{cluster="tuist-production"})
)

max by (namespace, pod, container) (
  increase(kube_pod_container_status_restarts_total{namespace="tuist"}[15m])
) * on (namespace, pod) group_left (node) kube_pod_info{namespace="tuist"}

sum by (cluster, proxy) (
  label_replace(
    label_replace(
      kube_statefulset_status_replicas_ready{namespace="tailscale-operator"},
      "proxy", "$1", "statefulset", "(.+)"
    ),
    "proxy", "$1", "statefulset", "ts-(.+)-[a-z0-9]{5}"
  )
)
and on (cluster, proxy)
sum by (cluster, proxy) (
  label_replace(
    label_replace(
      kube_statefulset_replicas{namespace="tailscale-operator"},
      "proxy", "$1", "statefulset", "(.+)"
    ),
    "proxy", "$1", "statefulset", "ts-(.+)-[a-z0-9]{5}"
  )
) > 0
